const AVB_mod = function (key, amount) { return new AVB_Modifier(AVB_RL.fromNamespaceAndPath('avgustov', key), amount, AVB_Op.ADD_VALUE); };
// a script error here would be thrown from every attribute lookup: wrapped, first error logged once
var AVB_FAILED = false;
NativeEvents.onEvent(AVB_Event, function (e) {
 try {
  var id = String(AVB_Registries.ITEM.getKey(e.getItemStack().getItem()));
  var a = AVB_ARMOR[id];
  if (a) {
    var g = AVB_Group[a[0]], slot = a[0].toLowerCase();
    e.removeAllModifiersFor(AVB_Attributes.ARMOR);
    e.removeAllModifiersFor(AVB_Attributes.ARMOR_TOUGHNESS);
    e.removeAllModifiersFor(AVB_Attributes.KNOCKBACK_RESISTANCE);
    if (a[1]) e.addModifier(AVB_Attributes.ARMOR, AVB_mod('tier_armor_' + slot, a[1]), g);
    if (a[2]) e.addModifier(AVB_Attributes.ARMOR_TOUGHNESS, AVB_mod('tier_toughness_' + slot, a[2]), g);
    if (a[3]) e.addModifier(AVB_Attributes.KNOCKBACK_RESISTANCE, AVB_mod('tier_knockback_' + slot, a[3]), g);
    if (a[4]) e.addModifier(AVB_Attributes.MAX_HEALTH, AVB_mod('tier_health_' + slot, a[4]), g);
    return;
  }
  var w = AVB_WEAPON[id];
  if (w) {
    e.removeAllModifiersFor(AVB_Attributes.ATTACK_DAMAGE);
    e.removeAllModifiersFor(AVB_Attributes.ATTACK_SPEED);
    e.addModifier(AVB_Attributes.ATTACK_DAMAGE, new AVB_Modifier(AVB_Item.BASE_ATTACK_DAMAGE_ID, w[0] - 1, AVB_Op.ADD_VALUE), AVB_Group.MAINHAND);
    e.addModifier(AVB_Attributes.ATTACK_SPEED, new AVB_Modifier(AVB_Item.BASE_ATTACK_SPEED_ID, w[1] - 4, AVB_Op.ADD_VALUE), AVB_Group.MAINHAND);
  }
 } catch (err) { if (!AVB_FAILED) { AVB_FAILED = true; console.error('[avgustov] balance hook failed: ' + err); } }
});
